#!/usr/bin/env python3
"""Legacy Era CP2 audited source close-read validator. Audit-only: no production modifications."""
import argparse, pathlib, json, hashlib, zipfile
BASE=pathlib.Path(__file__).resolve().parents[3];DATA=BASE/'data/audits/vehicles'
SHA='344d172e21daa7fdb3e0b032671e6833122f95d1175cf943bb1bb4a8110c561d'
def require(test,message):
 if not test:raise AssertionError(message)
def main(args):
 l=json.loads((DATA/'swse-phase2b-legacy-era-cp2-per-entry-source-review-ledger.json').read_text());m=json.loads((DATA/'swse-phase2b-legacy-era-cp2-weapon-mount-backlog.json').read_text());s=json.loads((DATA/'swse-phase2c-legacy-era-cp2-schema-discovery.json').read_text());es=l['entries'];keys=[e['sourceEntryKey'] for e in es];idx={e['sourceEntryKey']:e for e in es}
 require(len(es)==len(set(keys))==39,'Identity count / collision');require([e['endPageReviewStatus'] for e in es]==['PDF_VERIFIED']*20+['NOT_REVIEWED']*19,'20/39 reviewed count');require(l['counts']['primaryPdfCloseReads']==20 and l['counts']['primaryPdfCloseReadsOutstanding']==19,'Cumulative counts');require(l['counts']['strictFullFieldAndPhysicalWeaponMountCertificates']==0,'Strict certification not authorized');require(all(not e['fullFieldCertified'] and not e['fullWeaponMountReconciled'] for e in es),'Illegitimate full cert');require(all(e['printedFacts'] is None and not e['mountAndFiringGroups'] for e in es[20:]),'Unreviewed data populated')
 w=sum(len(e['mountAndFiringGroups']) for e in es[:20]);require(w==36==l['counts']['attackGroupRowsReviewed']==m['counts']['weaponAttackGroups'],'Weapon attack-group inventory');require(len(m['entries'])==39 and {e['sourceEntryKey'] for e in m['entries']}==set(keys),'Mount backlog count/keys');require(len(s['cases'])==34 and all(not c['productionMutationAuthorized'] for c in s['cases']) and not s['schemaFrozen'] and not s['productionMutationAuthorized'],'Discovery-only schema guard');require(l['sourcePdfSha256']==SHA,'PDF SHA field wrong');require(l['counts']['sourceConflictRecordCount']==4,'Conflict count must include I4')
 for key,field in [('le-j-1-shuttle','rangedAttack'),('le-bb-2-starfire-fighter-bomber','crew'),('le-i4-ionizer-starfighter','initiativeSenses'),('le-scarlet-star-modified-yt-2400-transport','initiativeSenses')]:require(idx[key]['fieldGroups'][field]=='SOURCE_CONFLICT_PRESERVED',f'Conflict lost: {key}')
 require(idx['le-i4-ionizer-starfighter']['printedFacts']['supplementalPrintedFacts']['skillsInitiative']==9,'I4 skill conflict value lost');require(idx['le-bb-2-starfire-fighter-bomber']['printedFacts']['supplementalPrintedFacts']['regeneratingShieldsRecoverySR']==10,'BB2 shield recovery');require(len(idx['le-bb-2-starfire-fighter-bomber']['mountAndFiringGroups'])==5,'BB2 weapon group topology');require(idx['le-jumpstar-hpf-starfighter']['printedFacts']['supplementalPrintedFacts']['hyperspacePursuit']['taggedTargetDC']==15,'Tracking pursuit DC');require(idx['le-mt-dropship']['fieldGroups']['hyperdrive']=='NARRATIVE_CONFIRMED_ABSENT','MT narrative drive status');require(idx['le-scarlet-star-modified-yt-2400-transport']['fieldGroups']['hyperdrive']=='SOURCE_SILENT_CONFIRMED','Scarlet source-silent drive');require(idx['le-crix-class-assault-shuttle']['mountAndFiringGroups'][1]['printedRangedBatteryCount']==2,'Crix battery count')
 if args.cp1_zip:
  with zipfile.ZipFile(args.cp1_zip) as z:old=json.loads(z.read(next(n for n in z.namelist() if n.endswith('cp1-per-entry-source-review-ledger.json'))))
  require(es[:10]==old['entries'][:10],'CP1 reviewed entry object mutated');require([e['sourceEntryKey'] for e in es]==[e['sourceEntryKey'] for e in old['entries']],'Original roster reordering');print('PASS: all ten CP1 reviewed records preserved exactly')
 if args.phase1:
  source=json.loads(pathlib.Path(args.phase1).read_text());b=next(x for x in source['books'] if x['book']=='Legacy Era Campaign Guide');actual={e['sourceEntryKey']:(e['printedName'],e['printedStatblockStartPage'],e['phase1PdfPhysicalPage']) for e in es};expected={e['sourceEntryKey']:(e['shipName'],e['printedStatblockPage'],e['pdfPhysicalPage']) for e in b['entries']};require(actual==expected,'Phase1 identity/page discrepancy');print('PASS: original Phase1 identities/names/pages unchanged')
 elif args.require_phase1:raise AssertionError('Supply --phase1 with --require-phase1')
 if args.source_pdf:require(hashlib.sha256(pathlib.Path(args.source_pdf).read_bytes()).hexdigest()==SHA,'Source PDF fingerprint mismatch');print('PASS: original PDF SHA-256')
 print('PASS: Legacy Era 20/39 source reviews, 19 pending, 36 weapon attack groups, 4 printed conflicts, 0 strict certificates');print('PASS: 34 schema discovery only; no production hydration')
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--source-pdf');p.add_argument('--phase1');p.add_argument('--require-phase1',action='store_true');p.add_argument('--cp1-zip');main(p.parse_args())
